3: // Every application gets private storage. Copies prevent accidental mutations
4: // outside explicit save operations. A database adapter could replace this layer.
5: export function createMemoryRepositories({ maximumAuditEvents }) {
6:   const users = new Map();
7:   const products = new Map();
8:   const orders = new Map();
9:   const sessions = new Map();
10:   const idempotencyRecords = new Map();
11:   const auditEvents = [];
12:   const copy = value => value === undefined ? undefined : structuredClone(value);
13: 
14:   function createEntityRepository(records) {
15:     return {
16:       findById(identifier) { return copy(records.get(identifier)); },
17:       findAll() { return [...records.values()].map(copy); },
18:       save(entity) {
19:         records.set(entity.id, copy(entity));
20:         return copy(entity);
21:       },
22:     };
23:   }
24: 
25:   return {
26:     users: {
27:       ...createEntityRepository(users),
28:       findByEmail(email) {
29:         return copy([...users.values()].find(user => user.email === email));
30:       },
31:     },
32:     products: createEntityRepository(products),
33:     orders: createEntityRepository(orders),
34:     sessions: {
35:       findByTokenHash(tokenHash) { return copy(sessions.get(tokenHash)); },
36:       save(session) { sessions.set(session.tokenHash, copy(session)); },
37:       deleteByTokenHash(tokenHash) { sessions.delete(tokenHash); },
38:       deleteByUserId(userId) {
39:         for (const [tokenHash, session] of sessions) {
40:           if (session.userId === userId) sessions.delete(tokenHash);
41:         }
42:       },
43:       deleteExpired(now) {
44:         for (const [tokenHash, session] of sessions) {
45:           if (session.expiresAt <= now) sessions.delete(tokenHash);
46:         }
47:       },
48:     },
49:     idempotency: {
50:       findByKey(key) { return copy(idempotencyRecords.get(key)); },
51:       save(key, record) { idempotencyRecords.set(key, copy(record)); },
52:       count() { return idempotencyRecords.size; },
53:       deleteExpired(now) {
54:         for (const [key, record] of idempotencyRecords) {
55:           if (record.expiresAt <= now) idempotencyRecords.delete(key);
56:         }
57:       },
58:     },
59:     audit: {
60:       append(event) {
61:         auditEvents.push(copy({ id: randomUUID(), ...event }));
62:         if (auditEvents.length > maximumAuditEvents) auditEvents.shift();
63:       },
64:       findAll() { return auditEvents.map(copy); },
65:     },
66:   };
67: }

