6: export const allowedOrderTransitions = Object.freeze({
7:   placed: Object.freeze(['confirmed', 'cancelled']),
8:   confirmed: Object.freeze(['shipped', 'cancelled']),
9:   shipped: Object.freeze(['delivered']),
10:   delivered: Object.freeze([]),
11:   cancelled: Object.freeze([]),
12: });
