14: export function createOrderService({ repositories, productService, auditService, configuration, clock }) {
15:   function requireAccessibleOrder(orderId, actor) {
16:     const order = repositories.orders.findById(orderId);
17:     if (!order) throw new ApplicationError(404, 'ORDER_NOT_FOUND', 'Order not found');
18:     if (order.customerId !== actor.id && !hasPermission(actor, 'orders:read-all')) {
19:       throw new ApplicationError(403, 'ORDER_ACCESS_DENIED', 'This order belongs to another customer');
20:     }
21:     return order;
22:   }
23: 
24:   function transitionOrder(order, nextStatus, actor, requestId) {
25:     if (!allowedOrderTransitions[order.status].includes(nextStatus)) {
26:       throw new ApplicationError(409, 'INVALID_ORDER_TRANSITION',
27:         'Cannot transition an order from ' + order.status + ' to ' + nextStatus);
28:     }
29:     const timestamp = new Date(clock()).toISOString();
30:     if (nextStatus === 'cancelled') {
31:       // Archived products still exist so their reserved inventory can be restored.
32:       const restoredProducts = order.items.map(item => {
33:         const product = productService.requireProduct(item.productId, true);
34:         product.stockQuantity += item.quantity;
35:         if (product.stockQuantity > 1000000) {
36:           throw new ApplicationError(409, 'STOCK_CAPACITY_EXCEEDED',
37:             'Cancellation would exceed inventory capacity; adjust inventory first');
38:         }
39:         product.version += 1;
40:         product.updatedAt = timestamp;
41:         return product;
42:       });
43:       restoredProducts.forEach(product => repositories.products.save(product));
44:     }
45:     order.status = nextStatus;
46:     order.updatedAt = timestamp;
47:     order.statusHistory.push({ status: nextStatus, changedAt: timestamp, actorId: actor.id });
48:     const savedOrder = repositories.orders.save(order);
49:     auditService.recordEvent('order.status_changed', actor.id, order.id, requestId, { status: nextStatus });
50:     return savedOrder;
51:   }
52: 
53:   return {
54:     requireAccessibleOrder,
55:     createOrder(actor, input, idempotencyKey, requestId) {
56:       const now = clock();
57:       repositories.idempotency.deleteExpired(now);
58:       const scopedKey = actor.id + ':orders:create:' + idempotencyKey;
59:       // Normalize item order so semantically identical retries have the same fingerprint.
60:       const canonicalItems = [...input.items].sort((left, right) => left.productId.localeCompare(right.productId));
61:       const fingerprint = createHash('sha256').update(JSON.stringify(canonicalItems)).digest('hex');
62:       const previousRequest = repositories.idempotency.findByKey(scopedKey);
63:       if (previousRequest) {
64:         if (previousRequest.fingerprint !== fingerprint) {
65:           throw new ApplicationError(409, 'IDEMPOTENCY_CONFLICT', 'This key was already used for different order items');
66:         }
67:         return { order: previousRequest.response, replayed: true };
68:       }
69:       if (repositories.idempotency.count() >= configuration.maximumIdempotencyRecords) {
70:         throw new ApplicationError(503, 'IDEMPOTENCY_CAPACITY_REACHED', 'Order creation is temporarily unavailable');
71:       }
72: 
73:       // Validate every line BEFORE changing any inventory.
74:       const inventoryReservations = input.items.map(item => {
75:         const product = productService.requireProduct(item.productId);
76:         if (product.stockQuantity < item.quantity) {
77:           throw new ApplicationError(409, 'INSUFFICIENT_STOCK', 'Insufficient stock for ' + product.name);
78:         }
79:         return { product, quantity: item.quantity };
80:       });
81:       const orderItems = inventoryReservations.map(({ product, quantity }) => ({
82:         productId: product.id, productName: product.name,
83:         unitPriceCents: product.priceCents, quantity,
84:         lineTotalCents: product.priceCents * quantity,
85:       }));
86:       const timestamp = new Date(now).toISOString();
87:       const order = {
88:         id: randomUUID(), customerId: actor.id, status: 'placed', items: orderItems,
89:         totalCents: orderItems.reduce((total, item) => total + item.lineTotalCents, 0),
90:         createdAt: timestamp, updatedAt: timestamp,
91:         statusHistory: [{ status: 'placed', changedAt: timestamp, actorId: actor.id }],
92:       };
93:       // No await within this critical section: one Node process cannot interleave
94:       // another request here. A real database needs a transaction and unique key.
95:       for (const { product, quantity } of inventoryReservations) {
96:         product.stockQuantity -= quantity;
97:         product.version += 1;
98:         product.updatedAt = timestamp;
99:         repositories.products.save(product);
100:       }
101:       repositories.orders.save(order);
102:       repositories.idempotency.save(scopedKey, {
103:         fingerprint, response: order, expiresAt: now + configuration.idempotencyLifetimeMilliseconds,
104:       });
105:       auditService.recordEvent('order.created', actor.id, order.id, requestId, { totalCents: order.totalCents });
106:       return { order, replayed: false };
107:     },
108:     listOrders(actor, query) {
109:       const orders = repositories.orders.findAll().filter(order =>
110:         (order.customerId === actor.id || hasPermission(actor, 'orders:read-all')) &&
111:         (!query.status || order.status === query.status));
112:       orders.sort((left, right) => right.createdAt.localeCompare(left.createdAt) || left.id.localeCompare(right.id));
113:       return paginateRecords(orders, query);
114:     },
115:     cancelOrder(orderId, actor, requestId) {
116:       const order = requireAccessibleOrder(orderId, actor);
117:       return transitionOrder(order, 'cancelled', actor, requestId);
118:     },
119:     updateOrderStatus(orderId, nextStatus, actor, requestId) {
120:       if (!hasPermission(actor, 'orders:manage')) {
121:         throw new ApplicationError(403, 'PERMISSION_DENIED', 'Order management permission is required');
122:       }
123:       return transitionOrder(requireAccessibleOrder(orderId, actor), nextStatus, actor, requestId);
124:     },
125:   };
126: }
